    @Override
    public boolean isWrapperFor(Wrapper wrapper, Class<?> iface) throws SQLException {
        if (this.pos < filterSize) {
            return nextFilter()
                    .isWrapperFor(this, wrapper, iface);
        }

        if (wrapper instanceof DruidStatementConnection) {
            if (iface.isInstance(((DruidStatementConnection) wrapper).getConnection())) {
                return true;
            }
        }

        // // if driver is for jdbc 3.0
        if (iface.isInstance(wrapper)) {
            return true;
        }

        return wrapper.isWrapperFor(iface);
    }

    @SuppressWarnings("unchecked")
    @Override
    public <T> T unwrap(Wrapper wrapper, Class<T> iface) throws SQLException {
        if (this.pos < filterSize) {
            return nextFilter()
                    .unwrap(this, wrapper, iface);
        }

        if (iface == null) {
            return null;
        }

        if (wrapper instanceof DruidStatementConnection) {
            Connection conn = ((DruidStatementConnection) wrapper).getConnection();
            if (iface.isAssignableFrom(conn.getClass())) {
                return (T) conn;
            }
        }

        // if driver is for jdbc 3.0
        if (iface.isAssignableFrom(wrapper.getClass())) {
            return (T) wrapper;
        }

        return wrapper.unwrap(iface);
    }

    public ConnectionProxy connection_connect(Properties info) throws SQLException {
        if (this.pos < filterSize) {
            return nextFilter()
                    .connection_connect(this, info);
        }

        Driver driver = dataSource.getRawDriver();
        String url = dataSource.getRawJdbcUrl();

        Connection nativeConnection = driver.connect(url, info);

        if (nativeConnection == null) {
            return null;
        }

        Statement stmt = nativeConnection.createStatement();
        Connection conn = new DruidStatementConnection(nativeConnection, stmt);
        return new ConnectionProxyImpl(dataSource, conn, info, dataSource.createConnectionId());
    }

